// ClientError A generic error.
type ClientError struct {
	// Code A Box-specific error code.
	//
	// Example: item_name_invalid
	Code *ClientErrorCode `json:"code,omitempty"`

	// ContextInfo A free-form object that contains additional context
	// about the error. The possible fields are defined on
	// a per-endpoint basis. `message` is only one example.
	//
	// Example: {"message":"Something went wrong"}
	ContextInfo *map[string]interface{} `json:"context_info,omitempty"`

	// HelpURL A URL that links to more information about why this error occurred.
	//
	// Example: https://developer.box.com/guides/api-calls/permissions-and-errors/common-errors/
	HelpURL *string `json:"help_url,omitempty"`

	// Message A short message describing the error.
	//
	// Example: Method Not Allowed
	Message *string `json:"message,omitempty"`

	// RequestID A unique identifier for this response, which can be used
	// when contacting Box support.
	//
	// Example: abcdef123456
	RequestID *string `json:"request_id,omitempty"`

	// Status The HTTP status of the response.
	//
	// Example: 400
	Status *int32 `json:"status,omitempty"`

	// Type The value will always be `error`.
	//
	// Example: error
	Type *ClientErrorType `json:"type,omitempty"`
}

// ClientErrorCode A Box-specific error code.
//
// Example: item_name_invalid
type ClientErrorCode string

// ClientErrorType The value will always be `error`.
//
// Example: error
type ClientErrorType string

// Collection A collection of items, including files and folders.
//
// Currently, the only collection available
// is the `favorites` collection.
//
// The contents of a collection can be explored in a
